        "Používa sa aj o fanatickom zanietení: von der Arbeit besessen sein, wie besessen arbeiten (pracovať ako posadnutý).",
        "Pozor: besessen je aj príčastie slovesa besitzen (vlastniť): Er hat ein Haus besessen. To je iné použitie; táto kartička je o prídavnom mene posadnutý."
