        "Tvary: ich schränke mich ein, schränkte mich ein, habe mich eingeschränkt. S auf + akuzatív sa vyjadruje, na čo sa niekto obmedzuje: sich auf das Nötigste einschränken. Bez doplnenia často znamená šetriť na výdavkoch.",
