        "Po ňom zvyčajne nasleduje genitív (sich seiner entsinnen, sich der Worte entsinnen), dnes aj an + akuzatív. Častá fráza: Soviel ich mich entsinne, … — pokiaľ si pamätám. Tvary: entsinnt sich, entsann sich, hat sich entsonnen."
