      "translation": "utrpenie • choroba",
      "explanation": [
        "Hlavná myšlienka: das Leiden je podstatné meno stredného rodu, ktoré sa používa dvojako: ako utrpenie (das Leiden der Menschen) a ako dlhodobá, často chronická choroba (ein schweres Leiden). Množné číslo je die Leiden.",
        "Slovo vzniklo zo slovesa leiden (trpieť). Typické spojenia: ein chronisches Leiden, ein altes Leiden, nach langem, schwerem Leiden (v smútočných oznámeniach).",
        "V porovnaní s bežným slovom Krankheit zdôrazňuje Leiden dĺžku a závažnosť choroby."
      ],
      "examples": [
        {
          "de": "Er hat ein schweres Leiden.",
          "lv": "Má ťažkú chorobu."
        },
        {
          "de": "Das Leiden der Patienten war groß.",
          "lv": "Utrpenie pacientov bolo veľké."
        },
        {
          "de": "Nach langem Leiden ist er gestorben.",
          "lv": "Zomrel po dlhom utrpení."
        },
        {
          "de": "Ein chronisches Leiden begleitet ihn seit Jahren.",
          "lv": "Chronická choroba ho sprevádza už roky."
        }
      ],
      "comparison": [
        {
          "word": "die Krankheit",
          "meaning": "choroba",
          "example": "Eine Krankheit kann ansteckend sein. – Choroba môže byť nákazlivá."
        },
        {
          "word": "der Schmerz",
          "meaning": "bolesť",
          "example": "Der Schmerz ist stark. – Bolesť je silná."
        },
        {
          "word": "leiden",
          "meaning": "trpieť",
          "example": "Er leidet an Asthma. – Trpí astmou."
        }
      ],
      "tip": [
        "So slovesom leiden povieš: an einer Krankheit leiden (trpieť nejakou chorobou).",
        "V smútočných oznámeniach často prečítaš: nach schwerem Leiden."
      ],
      "important": [
        "Leiden je podstatné meno s veľkým začiatočným písmenom, ale leiden je sloveso s malým.",
        "V bežnej reči sa o krátkodobej chorobe hovorí Krankheit, nie Leiden."
      ],
