        "Odlučiteľné sloveso: er bietet an, bot an, hat angeboten. Konštrukcia: jemandem etwas anbieten. S neurčitkom: Er bot an, mich zu fahren. Zvratné sich anbieten znamená ponúknuť sa, javiť sa ako vhodné: Das bietet sich an (to sa priam ponúka).",
